def combine_dicts(dict1, dict2, combine_lists=True):
    """
    Returns dict that combines copies of dict1 and dict2 keys and values.

    :param dict1: dictionary into which we want to copy dict2
    :type dict1: dict
    :param dict2: dictionary from which we want to copy
    :type dict2: dict
    :param combine_lists: When True: merges values into single sorted list if values are list type in
    both dicts for the same dictionary key e.g. [1, 2, 3, 4]
    When False: create list containing values from both dicts e.g. [[1, 2, 3], 'some_word'].
    :type combine_lists: bool
    :return: combined dict1 and dict2
    :rtype: dict
    """
    dict1 = copy.deepcopy(dict1)
    dict2 = copy.deepcopy(dict2)

    dict1_keys = dict1.keys()
    dict2_keys = dict2.keys()
    common_keys = [key for key in dict1_keys if key in dict2_keys]
    diffs = [key for key in dict2_keys if key not in dict1_keys]

    for comm_key in common_keys:
        if combine_lists and isinstance(dict1[comm_key], list) and isinstance(dict2[comm_key], list):
            dict1[comm_key] = sorted(dict1[comm_key] + dict2[comm_key])
        else:
            dict1[comm_key] = [dict1[comm_key], dict2[comm_key]]

    for diff_key in diffs:
        dict1[diff_key] = dict2[diff_key]

    return dict1


@log_input_and_output
def get_lmp_interface(address):
    """
    Get management interface
    :param address: Management interface address set to VM
    :type address: string
    :return: lmp interface when detected
    :rtype: str
    :raises: NoLmpInterfaceDetected when there is no lmp interface detected
    """
    for iface, addrs in psutil.net_if_addrs().items():
        for addr in addrs:
            if addr.family == socket.AF_INET and addr.address == address:
                return iface
    raise NoLmpInterfaceDetected(f'Error - No interface: {address}')


@log_input_and_output
def get_kpi_operation_name_for_rat_reset(rat):
    """
    Gets kpi selector's operation name for rat reset depending on rat.
    :param rat: rat type, e.g. "nr"
    :type rat: str
    :return: kpi selector's operation name for rat reset
    :rtype: str
    """
    return "{}_rat_reset".format(rat.lower())


def remove_duplicates_and_preserve_order(items):
    """
    Remove duplicates from list and preserve order
    :param items: list with duplicates
    :type items: list
    :return: list without duplicates
    :rtype: list
    """
    uniques = []
    [uniques.append(item) for item in items if item not in uniques]

    return uniques


def get_number_of_cells_after_cell_removal(number_of_cells_before_removal, cell_id_to_delete):
    if isinstance(cell_id_to_delete, list):
        return int(number_of_cells_before_removal) - len(cell_id_to_delete)
    else:
        return int(number_of_cells_before_removal) - 1


@log_input_and_output
def check_if_time_in_utc_format(time):
    """
    Checks if time string is in UTC Format.

    :param time: time string read from RFRES ManagedObject.
    :type time: str
    :raises: NotMatchingTimeFormat exception when time string is not in UTC Format manner.
    """
    pattern = r'[0-9]{2}\.[0-9]{2}\.\b[0-9]{4} [0-9]{2}:[0-9]{2}:[0-9]{2}'

    if not re.match(pattern, time):
        raise NotMatchingTimeFormat('{0} does not match UTC time format!'.format(time))


@log_input_and_output
def get_port_number_to_block_from_rmod_table_ip_filter(table_ip_filter):
    """
    Gets port number to block from rmod table ip filter from command:
    "sudo su -c 'nft -n -a list chain filter INPUT'"

    :param table_ip_filter: rmod table
    :type table_ip_filter: str
    :return: port number
    :rtype: str
    :raises: MissingPortNumber when port number to block has not been found in rmod table ip filter
    """
    table_ip_lines = table_ip_filter.replace('\r', '').replace('\t', '').split('\n')
    port_number = ''
    for line in table_ip_lines:
        if 'jump dynamic-chain' in line:
            port_number = line.split('handle')[-1].strip()
    if port_number.isdigit():
        return port_number
    raise MissingPortNumber('Port number to block has not been found in rmod table ip filter')


@log_input_and_output
def get_port_numbers_to_unblock_from_rmod_table_ip_filter(ip_address, table_ip_filter):
    """
    Gets ports numbers list to unblock from rmod table ip filter from command:
    "sudo su -c 'nft -n -a list chain filter INPUT'"
    :param ip_address: ip address to search for
    :type ip_address: str
    :param table_ip_filter: rmod table
    :type table_ip_filter: str
    :return: list of ports numbers
    :rtype: list of str
    :raises MissingPortNumber: when ports numbers to unblock have not been found in rmod table ip filter
    """
    table_ip_lines = table_ip_filter.replace('\r', '').replace('\t', '').split('\n')
    ports = [port.split('handle')[-1].strip() for port in table_ip_lines if ip_address in port and 'handle' in port]
    if not ports:
        raise MissingPortNumber('Ports numbers to unblock have not been found in rmod table ip filter')
    return ports


def get_datetime_with_utc_tz():
    """
    Returns current datetime with UTC timezone.
    :return: current datetime with UTC timezone
    :rtype: datetime
    """
    return datetime.now(pytz.utc)


def get_local_datetime():
    """
    Returns current datetime with local timezone (set on VM).
    :return: current datetime with local timezone
    :rtype: datetime
    """
    return datetime.now()


def convert_to_list(data):
    """
    Converts the input into a one-element list if it is not already a list.
    :param data: Item to convert to list
    :type data: int or str or list
    :return: A list containing the input data.
    :rtype: list
    """
    return [data] if not isinstance(data, list) else data


def convert_to_hex_pairs(hex_string):
    """
    Converts a hex string to a list of hex pairs.
    :param hex_string: Hex string to convert. e.g '00010203'
    :type hex_string: str
    :return: List of hex pairs. e.g ['00', '01', '02', '03']
    """
    return [hex_string[i:i + 2] for i in range(0, len(hex_string), 2)]


def is_str_matched_filters(input_str, filters):
    """
    Check if the given input_str matches any of the filter rules.

    A filter rule can be either:
    - A simple string, which checks for its presence in the str. e.g. filter = 'OneWayDelayMeasurement'
    - A compound filter containing multiple substrings separated by '&&'. filter = 'OneWayDelayMeasurement&&createPeriodicMeasurement'
      In this case, all substrings must be present in the input_str.
    - A list of filter rules. In this case, the input_str must match at least one filter rule. e.g. filters = ['OneWayMeasurement', 'handle&&Session']
    e.g. filters = ['handleCreateSessionReq:', 'DelayMeasurement:&&createPeriodicMeasurement:']
    if in above example input_str contains 'handleCreateSessionReq:' or ('DelayMeasurement:' and 'createPeriodicMeasurement:') then will return True

    :param input_str: The string to be checked.
    :type input_str: str
    :param filters: A filter or list of filter rules.
    :type filters: str | re.Pattern | list[str | re.Pattern]
    :return: True if the input_str matches at least one filter rule, False otherwise.
    """
    filters = convert_to_list(filters)
    for filter_rule in filters:
        if isinstance(filter_rule, re.Pattern):
            if filter_rule.search(input_str):
                return True
        elif '&&' in filter_rule:
            parts = [part for part in filter_rule.split('&&')]
            if all(re.search(rf'(^|\s){re.escape(part)}(\s|$)', input_str) for part in parts):
                return True
        else:
            if re.search(rf'(^|\s){re.escape(filter_rule)}(\s|$)', input_str):
                return True
    return False


def get_generator_items_number(generator):
    """Count the number of items in a generator or any iterator without consuming it.

    :param generator: Generator to check.
    :type generator: Iterator
    :return: Count of items. If the generator is empty, it returns 0
    :rtype: int
    """
    if generator is None:
        return 0

    try:
        generator, backup = itertools.tee(generator)
        count = sum(1 for _ in backup)
        return count
    except StopIteration:
        return 0


def append_to_file(file_path, data):
    """
    Write data to a file in append mode.

    :param file_path: Path to the file to write to.
    :type file_path: str
    :param data: Data to write to the file.
    :type data: str
    """
    with open(file_path, 'a') as file:
        file.write(data)


def convert_timestamp_to_datetime(timestamp, time_format):
    """
    Convert timestamp to datetime object.

    :param timestamp: Timestamp in string representation. e.g.: '2025-03-20T13:12:48.274000Z'
    :type timestamp: str
    :param time_format: Time format. e.g.: '%Y-%m-%dT%H:%M:%S.%fZ'
    :type time_format: str
    :return: Datetime object.
    :rtype: datetime
    """
    return datetime.strptime(timestamp, time_format)


def download_file_from_url(url, save_path, file_name=None, timeout=300):
    """
    Download a file from a given URL and save it to the specified path.

    :param url: URL of the file to download.
    :type url: str
    :param save_path: Path where the downloaded file will be saved e.g '/home/ute'
    :type save_path: str
    :param file_name: Optional name for the saved file. If not provided, the file will be saved with its original name. Default is None.
    :type file_name: str or None
    :param timeout: Timeout for the procedure. Default is 300 seconds.
    """
    if file_name is None:
        file_name = url.split('/')[-1]
    file_path = os.path.join(save_path, file_name)

    if os.path.isfile(file_path):
        log_result(f"File {file_name} already exists in dir: {save_path}. Skipping download.")
        return file_path

    with requests.get(url, stream=True, timeout=timeout) as r:
        r.raise_for_status()
        with open(file_path, "wb") as f:
            for chunk in r.iter_content(chunk_size=8192):
                f.write(chunk)

    return file_path
